/* ══ ORG DIRECTORY · EXPORT · PROCESSES SETTINGS ════════════════════════ */

/* the org directory: people come from the client's People register */
R.org = (args) => {
  const v = ['people', 'roles', 'chart'].indexOf(args[0]) >= 0 ? args[0] : 'people';
  return phead('Org directory', { sub: 'Roles and people are shared by every process map, RACI matrix and authority matrix. People come from the client\'s People register.', tiles: [[livePeople().length, 'People', 0, 'org~people'], [liveRoles().length, 'Roles', 0, 'org~roles'], [livePeople().filter((p) => p.reg).length, 'From the register', 0, 'org~people']], acts: v === 'chart' ? '<button class="bq" type="button" data-act="toast" data-msg="Downloads the org chart as a PDF in the product.">Export PDF</button>' : '' }) +
    '<div class="seg" style="margin-bottom:14px"><button type="button" class="' + (v === 'people' ? 'on' : '') + '" data-go="org~people">People <span class="c">' + livePeople().length + '</span></button><button type="button" class="' + (v === 'roles' ? 'on' : '') + '" data-go="org~roles">Roles <span class="c">' + liveRoles().length + '</span></button><button type="button" class="' + (v === 'chart' ? 'on' : '') + '" data-go="org~chart">Org chart</button></div>' +
    ({ people: orgPeople, roles: orgRoles, chart: orgChart })[v]();
};
function orgPeople() {
  return '<div class="sect">' + plural(livePeople().length, 'person', 'people') + ' <span>· ' + livePeople().filter((p) => p.reg).length + ' from the People register</span><span class="r"><button class="btn sm gold" type="button" data-act="personAdd">+ Add person</button></span></div>' +
    '<div class="tw"><table class="t"><thead><tr><th>Name</th><th>Email</th><th>Roles</th><th>Reports to</th><th></th></tr></thead><tbody>' + livePeople().map((p) => '<tr><td><b>' + esc(p.name) + '</b>' + (p.reg ? '' : ' <span class="chip" title="Added here, not on the People register">Added here</span>') + '</td><td>' + (p.email ? esc(p.email) : '<span class="q">—</span>') + '</td><td><div class="roles">' + (p.roles.length ? p.roles.map((r) => '<span>' + esc(roleName(r)) + '</span>').join('') : '<span class="q" style="border:0;background:none">No role</span>') + '</div></td>' +
      '<td>' + sel('mgr-' + p.id, [['', '— no manager —']].concat(livePeople().filter((x) => x !== p).map((x) => [x.id, x.name])), p.mgr || '', { chg: 'mgr', data: 'data-id="' + p.id + '" aria-label="Reports to"' }) + '</td><td class="r" style="white-space:nowrap"><button class="btn sm ghost" type="button" data-act="personEdit" data-id="' + p.id + '">Edit</button>' + (p.reg ? '' : '<button class="btn sm ghost danger" type="button" data-act="personDel" data-id="' + p.id + '">Delete</button>') + '</td></tr>').join('') + '</tbody></table></div>' +
    '<p class="note" style="margin-top:8px">Name and email of somebody on the People register follow the register; change them there. Roles and who they report to are set here.</p>';
}
CHG.mgr = (el) => {
  const p = personById(el.dataset.id), to = el.value || null;
  let x = to, loop = false; while (x) { if (x === p.id) { loop = true; break; } x = (personById(x) || {}).mgr; }
  if (loop) { toast('That manager selection would create a circular reporting line.'); render(); return; }
  p.mgr = to; toast('Saved.'); render();
};
ACT.personEdit = (el) => {
  const p = personById(el.dataset.id);
  dialog({ title: 'Edit ' + esc(p.name), sub: p.reg ? 'On the client\'s People register: name and email are changed there.' : 'Added in Processes, not on the People register.', body: '<div class="frm two">' + fld('Name', inp('pe-n', p.name, { ro: p.reg })) + fld('Email', inp('pe-e', p.email, { ro: p.reg, type: 'email' })) + fld('Roles', '<div class="checks" style="max-height:180px;overflow:auto;border:1px solid var(--line);border-radius:6px;padding:6px 8px">' + liveRoles().map((r) => '<label><input type="checkbox" name="pe-r" value="' + r.id + '"' + (p.roles.indexOf(r.id) >= 0 ? ' checked' : '') + '> ' + esc(r.name) + '</label>').join('') + '</div>', { full: true }) + '</div>',
    foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="personSave" data-id="' + p.id + '">Save</button>' });
};
ACT.personSave = (el) => { const p = personById(el.dataset.id); if (!p.reg) { p.name = val('pe-n') || p.name; p.email = val('pe-e'); } p.roles = checkedVals('pe-r'); UI.layer = null; toast('Saved.'); render(); };
ACT.personDel = (el) => { const p = personById(el.dataset.id); p.archived = true; toast(p.name + ' removed. Nothing they appear in is lost.'); render(); };
ACT.personAdd = () => dialog({ title: 'Add a person', sub: 'People on the client\'s People register appear here by themselves. Add somebody here only if they are not on it.', body: '<div class="frm two">' + fld('Name', inp('pa-n', ''), { req: true }) + fld('Email', inp('pa-e', '', { type: 'email' }), { hint: 'Optional, but they cannot sign in or approve without one.' }) + fld('Role', sel('pa-r', [['', '—']].concat(liveRoles().map((r) => [r.id, r.name])), '')) + fld('Reports to', sel('pa-m', [['', '— no manager —']].concat(livePeople().map((x) => [x.id, x.name])), '')) + '</div>',
  foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="personAddGo">Add person</button>' });
ACT.personAddGo = () => { const n = val('pa-n'); if (!n) return; S.people.push({ id: uid('p'), name: n, email: val('pa-e'), roles: val('pa-r') ? [val('pa-r')] : [], mgr: val('pa-m') || null, reg: false, archived: false }); UI.layer = null; toast('Added.'); render(); };
function orgRoles() {
  const used = (id) => procs().reduce((n, p) => n + p.steps.filter((s) => s.role === id).length, 0);
  return '<div class="filters"><input class="inp" id="role-new" placeholder="New role, e.g. Controller" style="max-width:280px" data-enter="roleAdd"><button class="btn sm gold" type="button" data-act="roleAdd">Add role</button></div>' +
    '<div class="tw"><table class="t"><thead><tr><th>Role</th><th>Held by</th><th>Steps given to it</th><th></th></tr></thead><tbody>' + liveRoles().map((r) => '<tr><td><b>' + esc(r.name) + '</b></td><td>' + (livePeople().filter((p) => p.roles.indexOf(r.id) >= 0).map((p) => esc(p.name)).join(', ') || '<span class="q">Nobody</span>') + '</td><td class="num">' + used(r.id) + '</td><td class="r" style="white-space:nowrap"><button class="btn sm ghost" type="button" data-act="roleEdit" data-id="' + r.id + '">Edit</button><button class="btn sm ghost danger" type="button" data-act="roleDel" data-id="' + r.id + '">Delete</button></td></tr>').join('') + '</tbody></table></div>';
}
ACT.roleAdd = () => { const n = val('role-new'); if (!n) return; if (liveRoles().some((r) => r.name.toLowerCase() === n.toLowerCase())) { toast('A role named “' + n + '” already exists in this workspace.'); return; } S.roles.push({ id: uid('r'), name: n, archived: false }); toast('Role added.'); render(); };
ACT.roleEdit = (el) => { const r = roleById(el.dataset.id); dialog({ title: 'Rename role', body: fld('Role', inp('ro-n', r.name)), foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="roleSave" data-id="' + r.id + '">Save</button>' }); };
ACT.roleSave = (el) => { const n = val('ro-n'); if (n) roleById(el.dataset.id).name = n; UI.layer = null; render(); };
ACT.roleDel = (el) => { const r = roleById(el.dataset.id); dialog({ title: 'Delete “' + esc(r.name) + '”?', body: '<p>The role is archived. Steps given to it keep their history and show as Unassigned on new maps.</p>', foot: '<button class="btn" type="button" data-act="close">No</button><button class="btn danger solid" type="button" data-act="roleDelGo" data-id="' + r.id + '">Yes, delete</button>' }); };
ACT.roleDelGo = (el) => { roleById(el.dataset.id).archived = true; UI.layer = null; render(); };
function orgChart() {
  const kids = (id) => livePeople().filter((p) => (p.mgr || null) === id);
  const node = (p) => '<li><span class="pn"><b>' + esc(p.name) + '</b><span>' + esc(p.roles.map(roleName).join(', ') || 'No role') + '</span></span>' + (kids(p.id).length ? '<ul>' + kids(p.id).map(node).join('') + '</ul>' : '') + '</li>';
  return '<p class="note" style="margin-bottom:8px">Built from each person\'s manager — set or change “Reports to” on the People view.</p><div class="tw"><div class="tree"><ul>' + kids(null).map(node).join('') + '</ul></div></div>';
}

/* export: the picker, the check, the report preview */
UI.f.exp = UI.f.exp || [];
R.export = (args) => {
  if (args[0] === 'preview') return exportPreview();
  const pk = UI.f.exp, all = procs(), n = pk.length;
  const res = UI.f.check;
  return phead('Export report', { sub: 'Pick which processes to include. The report opens as a clean, printable document — company name, a summary, the org structure, then each process\'s documentation. Anything not filled in is shown as not yet recorded.', tiles: [[n, 'Ticked'], [all.length, 'Processes']] }) +
    '<div class="ovgrid" style="grid-template-columns:minmax(0,1fr) minmax(0,1.2fr)"><div class="stack">' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Pack sections</span></div><p class="note" style="margin-bottom:8px">The parts that appear once, around the processes. Untick one to leave it out of this client\'s pack.</p>' + S.pack.map((x, i) => '<div class="filters" style="margin:0 0 4px' + (x.on ? '' : ';opacity:.55') + '"><label class="checks"><label><input type="checkbox" data-chg="packOn" data-i="' + i + '"' + (x.on ? ' checked' : '') + (x.locked ? ' disabled' : '') + '> ' + (x.on ? '' : '<s>') + esc(x.name) + (x.on ? '' : '</s>') + '</label></label><span style="margin-left:auto"><button class="btn sm ghost" type="button" data-act="packMove" data-i="' + i + '" data-d="-1" aria-label="Up">↑</button><button class="btn sm ghost" type="button" data-act="packMove" data-i="' + i + '" data-d="1" aria-label="Down">↓</button></span></div>').join('') + '</div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Inside each process</span></div><p class="note" style="margin-bottom:8px">These repeat for every process. Numbers follow the order.</p>' + S.inside.map((s, i) => '<div style="margin-bottom:6px"><label class="checks"><label><input type="checkbox" data-chg="insideOn" data-i="' + i + '"' + (s.on ? ' checked' : '') + '> <b>' + (i + 1) + '.0 ' + esc(s.name) + '</b></label></label>' + s.blocks.map((b, j) => '<label class="checks" style="margin:3px 0 0 24px"><label><input type="checkbox" data-chg="blockOn" data-i="' + i + '" data-j="' + j + '"' + (b.on ? ' checked' : '') + (s.on ? '' : ' disabled') + '> ' + (i + 1) + '.' + (j + 1) + ' ' + esc(b.name) + (b.id === 'ext' && !procs().some((p) => p.entities.length) ? ' <span class="chip attn">no data yet</span>' : '') + '</label></label>').join('') + '</div>').join('') + '</div></div>' +
    '<div class="stack"><div class="tw"><table class="t"><thead><tr><th><input type="checkbox" data-chg="expAll" aria-label="Select all"' + (n === all.length ? ' checked' : '') + '></th><th>Code</th><th>Process</th><th class="r">Order</th></tr></thead><tbody>' +
    (pk.concat(all.map((p) => p.code).filter((c) => pk.indexOf(c) < 0))).map((c) => { const p = byCode(c), on = pk.indexOf(c) >= 0; return '<tr><td><input type="checkbox" data-chg="expPick" data-code="' + c + '"' + (on ? ' checked' : '') + ' aria-label="Include ' + esc(p.name) + '"></td><td><span class="code">' + c + '</span></td><td>' + esc(p.name) + (p.parent ? '<span class="psub">under ' + p.parent + '</span>' : '') + '</td><td class="r">' + (on ? '<button class="btn sm ghost" type="button" data-act="expMove" data-code="' + c + '" data-d="-1">↑</button><button class="btn sm ghost" type="button" data-act="expMove" data-code="' + c + '" data-d="1">↓</button>' : '') + '</td></tr>'; }).join('') + '</tbody></table></div>' +
    '<p class="note">The report follows the order above. Arranging it here changes this pack only.</p>' +
    '<div class="acts"><button class="btn gold" type="button" data-act="expPreview"' + (n ? '' : ' disabled title="Tick at least one process to preview the report"') + '>Preview report →</button><button class="btn" type="button" data-act="expSop"' + (n ? '' : ' disabled title="Tick at least one process to see the SOP"') + '>SOP →</button><button class="btn" type="button" data-act="expCheck"' + (checkWhy(n) ? ' disabled title="' + esc(checkWhy(n)) + '"' : '') + '>Check ' + (n ? 'these ' + n : 'these') + ' end to end</button></div>' +
    (n > 12 ? '<p class="note" style="color:var(--attn-tx);font-weight:600">' + esc(checkWhy(n)) + '</p>' : '') +
    '<p class="note">The check is optional, and a warning only — the report opens either way. Nothing is saved.</p>' +
    (res ? '<div class="blk"><div class="blk-h"><span class="lbl">End-to-end check</span><span class="r note">' + res.counts + '</span></div>' + res.html + '</div>' : '') + '</div></div>';
};
CHG.packOn = (el) => { S.pack[el.dataset.i].on = el.checked; render(); };
ACT.packMove = (el) => { const i = Number(el.dataset.i), j = i + Number(el.dataset.d); if (j < 1 || j >= S.pack.length || i < 1) return; const t = S.pack[i]; S.pack[i] = S.pack[j]; S.pack[j] = t; render(); };
CHG.insideOn = (el) => { S.inside[el.dataset.i].on = el.checked; render(); };
CHG.blockOn = (el) => { S.inside[el.dataset.i].blocks[el.dataset.j].on = el.checked; render(); };
CHG.expAll = (el) => { UI.f.exp = el.checked ? procs().map((p) => p.code) : []; UI.f.check = null; render(); };
CHG.expPick = (el) => { const c = el.dataset.code, s = UI.f.exp; if (el.checked) s.push(c); else s.splice(s.indexOf(c), 1); UI.f.check = null; render(); };
ACT.expMove = (el) => { const s = UI.f.exp, i = s.indexOf(el.dataset.code), j = i + Number(el.dataset.d); if (j < 0 || j >= s.length) return; const t = s[i]; s[i] = s[j]; s[j] = t; UI.f.check = null; render(); };
ACT.expPreview = () => go('export~preview');
ACT.expSop = () => { UI.f.sopCodes = UI.f.exp.slice(); go('sop~pack'); };
/* the live module's rule since §658 (first numbered §599) (ffp/lib/domain/pack-check.ts): the button says why it cannot run */
function checkWhy(n) { return n < 1 ? 'Tick at least one process to check' : n > 12 ? 'The check reads up to 12 processes at a time and ' + n + ' are ticked. Untick ' + (n - 12) + ' to run it.' : null; }
ACT.expCheck = () => {
  const list = UI.f.exp.map(byCode);
  if (list.length > 12) { toast('Pick between 1 and 12 processes to check.'); return; }
  let hi = 0, md = 0, lo = 0;
  const groups = list.map((p) => { const f = findingsFor(p).filter((x) => x.status === 'New'); f.forEach((x) => { if (x.sev === 'high') hi++; else if (x.sev === 'medium') md++; else lo++; });
    return '<div style="margin-top:10px"><b><span class="code">' + p.code + '</span> ' + esc(p.name) + '</b> <span class="note">· <a class="lnk" href="#" data-go="' + openP(p.code, 'map') + '">map</a> · <a class="lnk" href="#" data-go="' + openP(p.code, 'raci') + '">RACI</a> · <a class="lnk" href="#" data-go="' + openP(p.code, 'authority') + '">authority</a></span>' + (f.length ? f.slice(0, 3).map((x) => '<div class="aif" style="padding:6px 0"><span><span class="chip ' + ({ high: 'bad', medium: 'attn', low: '' }[x.sev]) + '">' + x.sev + '</span> <b>' + esc(x.title) + '</b></span><span class="q">→ ' + esc(x.rec) + '</span></div>').join('') : '<p class="note">Fine — nothing to flag.</p>') + '</div>'; });
  const across = list.some((p) => p.code === 'ORD100') && !list.some((p) => p.code === 'LOG100') ? '<div class="aif"><span><span class="chip attn">medium</span> <b>Order-to-Cash hands over to Logistics &amp; Last-mile, which is not in this pack</b></span><span class="q">→ Add LOG100, or say in the report where the hand-over is documented.</span></div>' : '';
  if (across) md++;
  UI.f.check = { counts: hi + ' high · ' + md + ' medium · ' + lo + ' low', html: (across ? '<div class="lbl" style="margin-top:4px">Across these processes</div>' + across : '') + groups.join('') };
  render();
};
function exportPreview() {
  const list = UI.f.exp.map(byCode).filter(Boolean);
  if (!list.length) return '<div class="box"><div class="empty"><b>No processes picked</b><div class="acts">' + goBtn('export', '← Back to the picker') + '</div></div></div>';
  const on = (id) => (S.pack.find((x) => x.id === id) || {}).on;
  const gaps = list.filter((p) => !p.purpose).map((p) => esc(p.name) + ': purpose');
  const page = (p) => {
    const roles = [...new Set(p.steps.map((s) => s.role).filter(Boolean))], f = inForce(p);
    return '<div class="paper"><div style="background:linear-gradient(120deg,var(--brand),var(--brand-to));color:var(--brand-ink);border-radius:8px;padding:14px 16px;margin:-12px -16px 14px"><span class="code" style="color:inherit;opacity:.85">' + p.code + '</span>' + (p.parent ? ' <span style="opacity:.8;font-size:12px">under ' + p.parent + '</span>' : '') + '<h1 style="color:inherit">' + esc(p.name) + '</h1>' + (p.desc ? '<p style="opacity:.85">' + esc(p.desc) + '</p>' : '') + '</div>' +
      '<div class="meta">' + [['Status', STATUS[p.status]], ['Version', f ? 'v' + f.n : '—'], ['Effective date', p.doc.effective ? dt(p.doc.effective) : '—'], ['Approved by', p.doc.approvedBy || '—'], ['Review cycle', 'Every ' + p.reviewMonths + ' months' + (p.nextReview && p.status === 'PUBLISHED' ? ' · next ' + dt(p.nextReview) : '')], ['Process owner', personName(p.owner) || '—'], ['Process code', p.code], ['Document ID', 'RAYA-BPD-2026']].map(([k, x]) => '<div><em>' + k + '</em>' + esc(x) + '</div>').join('') + '</div>' +
      (S.inside[0].on ? '<h2>1.0 Executive Summary</h2><h3>1.1 Process Purpose</h3><p>' + (p.purpose ? esc(p.purpose) : '<span class="q">No data yet — nothing has been recorded for this section.</span>') + '</p><h3>1.3 Internal Roles</h3><p>' + (roles.map(roleName).map(esc).join(' · ') || '<span class="q">No data yet.</span>') + '</p>' : '') +
      (S.inside[1].on ? '<h2>2.0 Process Map &amp; Narrative</h2><ol class="steps">' + workSteps(p).map((s) => '<li><b>' + stepNo(p, s.id) + '. ' + esc(s.label) + '</b><span class="psub">Step owner: ' + esc(roleName(s.role)) + '</span>' + (s.actions.length ? '<ol style="padding-left:18px;margin-top:4px">' + s.actions.map((a) => '<li>' + esc(a) + '</li>').join('') + '</ol>' : '') + '</li>').join('') + '</ol>' : '') +
      (S.inside[2].on && raciRows(p).length ? '<h2>3.0 RACI &amp; Authority Matrix</h2><div class="tw"><table class="t"><thead><tr><th>Step</th>' + raciCols(p).map((c) => '<th class="c" style="white-space:normal">' + esc(roleName(c)) + '</th>').join('') + '</tr></thead><tbody>' + raciRows(p).map((r) => '<tr><td>' + esc(r.label) + '</td>' + raciCols(p).map((c) => '<td class="c">' + (p.raci.cells[raciKey(r.id, c)] || '') + '</td>').join('') + '</tr>').join('') + '</tbody></table></div>' : '') +
      (S.inside[3].on ? '<h2>4.0 Governance, Controls &amp; Metrics</h2>' + (p.kpis.length ? '<ul>' + p.kpis.map((k) => '<li>' + esc(k.metric) + ' — ' + esc(k.target) + ', ' + esc(k.freq.toLowerCase()) + '</li>').join('') + '</ul>' : '<p class="q">No data yet — nothing has been recorded for this section.</p>') : '') + '</div>';
  };
  return '<div class="toolbar">' + goBtn('export', '← Back to picker') + '<div class="seg"><button type="button">Tight</button><button type="button">Compact</button><button type="button" class="on">Default</button><button type="button">Roomy</button></div><span class="r"><button class="btn" type="button" data-act="toast" data-msg="Downloads the pack as PowerPoint in the product.">Download PPTX</button><button class="btn gold" type="button" data-act="toast" data-msg="Opens the browser\'s print dialog in the product.">Print / save as PDF</button></span></div>' +
    (gaps.length ? '<div class="banner attn" style="max-width:860px;margin:0 auto 12px">⚠ Some sections have nothing recorded yet and print as empty: ' + gaps.join(' · ') + '. Fill them in on each process, or untick them on the picker.</div>' : '') +
    (on('cover') ? '<div class="paper" style="min-height:360px;display:grid;align-content:space-between"><div><div class="crumb">Business process documentation &amp; procedure standard</div><h1 style="font-size:34px">' + esc(S.ws.name) + '</h1><p class="q">' + esc(S.ws.about) + '</p></div><div class="two"><dl class="dl"><dt>Document ID</dt><dd>RAYA-BPD-2026</dd><dt>Version</dt><dd>1.0</dd><dt>Effective date</dt><dd>' + dt(todayIso()) + '</dd><dt>Classification</dt><dd>Internal — Confidential</dd><dt>Prepared by</dt><dd>Forefront Consulting</dd></dl><div><b>Contents — ' + plural(list.length, 'process', 'processes') + '</b><ol style="padding-left:18px">' + list.slice(0, 6).map((p) => '<li>' + p.code + ' · ' + esc(p.name) + '</li>').join('') + '</ol></div></div></div><div style="height:16px"></div>' : '') +
    (on('index') ? '<div class="paper"><h1>Processes in this report</h1><p class="q">' + plural(list.length, 'process', 'processes') + ', in the order they follow.</p><ol style="padding-left:18px;margin-top:10px">' + list.map((p) => '<li><span class="code">' + p.code + '</span> ' + esc(p.name) + ' <span class="q">· ' + (p.parent ? 'under ' + p.parent : 'top-level') + '</span></li>').join('') + '</ol></div><div style="height:16px"></div>' : '') +
    list.map(page).join('<div style="height:16px"></div>') +
    (on('close') ? '<div style="height:16px"></div><div class="paper" style="text-align:center"><h1>Thank you</h1><p class="q">Please refer back to the process team for any inputs or comments needed.</p></div>' : '');
}

/* processes settings: everything that was on the old Dashboard and the governance profile */
R.settings = () => {
  const c = S.ws.colors;
  return phead('Processes settings', { eyebrow: '<a href="#" data-go="overview">' + esc(S.ws.name) + ' · Processes</a> › Settings', sub: 'What used to sit on the Dashboard, plus the governance profile. Reached from the Processes menu in the top bar.' }) +
    '<div class="two"><div class="blk"><div class="blk-h"><span class="lbl">Client logo and colours</span></div><div class="filters" style="align-items:flex-start"><div class="logo-box">' + (S.ws.logo ? '<img src="' + S.ws.logo + '" alt="Client logo">' : 'No logo') + '</div><div class="stack" style="gap:8px"><label class="btn sm" style="cursor:pointer">' + (S.ws.logo ? 'Replace logo' : 'Upload logo') + '<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" data-chg="logo" style="display:none"></label>' + (S.ws.logo ? '<button class="btn sm ghost" type="button" data-act="logoRemove">Remove</button>' : '') + '<span class="note">PNG, JPEG, WebP or SVG, under 300 KB.</span></div></div>' +
    '<div class="filters" style="margin-top:10px">' + ['Primary', 'Secondary', 'Tertiary'].map((l, i) => '<label class="swatch"><input type="color" value="' + c[i] + '" data-chg="color" data-i="' + i + '" aria-label="' + l + ' colour"> ' + l + '</label>').join('') + '</div><p class="note" style="margin-top:6px">Used on the report and the SOP' + (OPT.brand ? ', and on page titles (option B of question 1)' : '') + '.</p></div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Client profile</span><button class="pen" type="button" data-act="profEdit">Edit</button></div><dl class="dl"><dt>Industry</dt><dd>' + esc(S.ws.industry || 'No industry set') + '</dd><dt>About</dt><dd>' + esc(S.ws.about || 'No background notes yet.') + '</dd></dl><p class="note" style="margin-top:6px">Helps Check with AI and the drafts suit this client.</p></div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Governance profile</span></div><div class="frm two">' + fld('Company size', sel('gp-size', ['Early-stage startup', 'Growth-stage', 'Mid-market', 'Public corporation'], S.gov.profile.size, { chg: 'gpSize' })) + fld('Jurisdiction', inp('gp-j', S.gov.profile.jurisdiction, { ph: 'e.g. United States (DE) · EU (IE)' }).replace('<input', '<input data-chg="gpJur"')) + '</div><p class="note" style="margin-top:6px">Grounds every governance assessment in this client\'s scale and legal context.</p></div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Categories</span></div><div class="roles">' + S.categories.map((x) => '<span>' + esc(x) + '</span>').join('') + '</div><p class="note" style="margin-top:6px">Shown as Department on Priorities and on the list.</p></div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Language</span></div>' + langSwitch() + '<p class="note" style="margin-top:6px">Each person\'s own choice, kept for a year in their browser.</p></div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Who opens Processes</span></div><p>The Strategy Office edits. A client\'s own people see only their reading page: what is published, and what waits for their approval.</p></div></div>';
};
CHG.logo = (el) => { const f = el.files && el.files[0]; if (!f) return; if (f.size > 300 * 1024) { toast('Logo file is too large — please use an image under 300 KB.'); return; } const r = new FileReader(); r.onload = () => { S.ws.logo = r.result; toast('Logo saved.'); render(); }; r.readAsDataURL(f); };
ACT.logoRemove = () => { S.ws.logo = null; S.ws.colors = ['#334155', '#4338CA', '#4338CA']; render(); };
CHG.color = (el) => { S.ws.colors[el.dataset.i] = el.value; render(); };
CHG.gpSize = (el) => { S.gov.profile.size = el.value; toast('Saved.'); };
CHG.gpJur = (el) => { S.gov.profile.jurisdiction = el.value.trim(); toast('Saved.'); };
ACT.profEdit = () => dialog({ title: 'Client profile', body: '<div class="frm">' + fld('Industry / sector', inp('pf-i', S.ws.industry, { max: 120, ph: 'e.g. Manufacturing' })) + fld('About this organisation', area('pf-a', S.ws.about, { rows: 4, ph: 'Size, specific practices, sector nuances — helps Check with AI suit its suggestions to this client.' })) + '</div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="profSave">Save</button>' });
ACT.profSave = () => { S.ws.industry = val('pf-i'); S.ws.about = val('pf-a'); UI.layer = null; toast('Saved.'); render(); };
